// LoadHousehold loads the householdMember's Household into the .R struct
func (os HouseholdMemberSlice) LoadHousehold(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	households, err := os.Household(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Household = nil
		o.R.Loaded.Household = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	householdMemberByKey := make(map[uuid.UUID][]*HouseholdMember, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		householdMemberByKey[o.HouseholdID] = append(householdMemberByKey[o.HouseholdID], o)
	}

	for _, rel := range households {

		owners, ok := householdMemberByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.Household != nil {
				continue
			}

			rel.R.HouseholdMembers = append(rel.R.HouseholdMembers, o)

			o.R.Household = rel

		}
	}

	return nil
}

