// PreloadCount sets a count in the C struct by name
func (o *HouseholdMember) PreloadCount(name string, count int64) error {
	if o == nil {
		return nil
	}

	switch name {
	case "CorrectionMemberBurdens":
		o.C.CorrectionMemberBurdens = &count
	case "JournalEntries":
		o.C.JournalEntries = &count
	case "PoolFundingRules":
		o.C.PoolFundingRules = &count
	case "PoolFundingShares":
		o.C.PoolFundingShares = &count
	case "PurchaseMemberBurdens":
		o.C.PurchaseMemberBurdens = &count
	case "PurchasePaymentFundingSnapshots":
		o.C.PurchasePaymentFundingSnapshots = &count
	}
	return nil
}

